<template><section class="ui-chart-frame" :aria-busy="loading"><header><div><h3>{{title}}</h3><p v-if="description">{{description}}</p></div><div class="ui-chart-frame__tools"><slot name="legend"/><slot name="actions"/></div></header><div class="ui-chart-frame__body" :style="{minHeight:`${height}px`}"><UiLoadingOverlay v-if="loading" :show="true" label="正在加载图表"/><UiErrorState v-else-if="error" title="图表加载失败" :description="error" @retry="emit('retry')"/><UiEmptyState v-else-if="empty" title="暂无趋势数据"/><slot v-else/></div><footer v-if="updatedAt||$slots.footer"><span v-if="updatedAt">更新于 {{updatedAt}}</span><slot name="footer"/></footer></section></template>
<script setup lang="ts">import UiEmptyState from './UiEmptyState.vue';import UiErrorState from './UiErrorState.vue';import UiLoadingOverlay from './UiLoadingOverlay.vue';withDefaults(defineProps<{title:string;description?:string;loading?:boolean;empty?:boolean;error?:string;updatedAt?:string;height?:number}>(),{loading:false,empty:false,height:220});const emit=defineEmits<{retry:[]}>();</script>
